//! Fork: `reason` and `retryable` of every provider business code, against Node's table
//! (`tests/fixtures/node-provider-codes.json`, generated by Node's `classifyModelFailure`). Node reads these from its
//! mapping table per code; a few zhipu codes that Node does not map fall back to the HTTP status (429 retries).

use std::time::SystemTime;

use rust_cli_kernel_api::model::ProviderFailure;
use rust_cli_kernel_api::provider::WireProtocol;
use rust_cli_net::ResponseHeaders;
use serde_json::{Value, json};

use crate::errors::{Vendor, Verdict};

const FIXTURE: &str = include_str!("../../tests/fixtures/node-provider-codes.json");

fn rows() -> Vec<Value> {
    let fixture: Value = serde_json::from_str(FIXTURE).expect("the Node fixture is JSON");
    fixture["rows"].as_array().expect("rows").clone()
}

fn provider_of(verdict: &Verdict) -> ProviderFailure {
    verdict
        .error
        .provider()
        .cloned()
        .unwrap_or_else(|| panic!("no provider code on {:?}", verdict.error))
}

fn zhipu_response(code: &str, status: u16) -> Verdict {
    let body = json!({"error": {"code": code, "message": "x"}}).to_string();
    crate::errors::classify_response(
        Vendor::Zhipu,
        WireProtocol::AnthropicMessages,
        (status, &ResponseHeaders::default()),
        &body,
        SystemTime::UNIX_EPOCH,
    )
}

fn zhipu_stream(code: &str) -> Verdict {
    let value = json!({"error": {"code": code, "message": "x"}});
    crate::errors::classify_stream_error(
        Vendor::Zhipu,
        WireProtocol::AnthropicMessages,
        &value,
        &value.to_string(),
    )
}

fn plan_response(code: &str, status: u16) -> Verdict {
    let body = json!({"error": {"type": "invalid_request_error", "code": code, "message": "x"}});
    crate::errors::classify_response(
        Vendor::Generic,
        WireProtocol::OpenAiResponses,
        (status, &ResponseHeaders::default()),
        &body.to_string(),
        SystemTime::UNIX_EPOCH,
    )
}

fn is_plan_code(code: &str) -> bool {
    code.starts_with("subscription_sharing_") || code.starts_with("chatpass_v2_")
}

fn verdict_for(code: &str, status: Option<u16>) -> Verdict {
    match (is_plan_code(code), status) {
        (true, Some(status)) => plan_response(code, status),
        (true, None) => {
            // A plan code in a stream: the same table, with no status.
            let value = json!({"type": "error", "error": {"type": "invalid_request_error", "code": code, "message": "x"}});
            crate::errors::classify_stream_error(
                Vendor::Generic,
                WireProtocol::OpenAiResponses,
                &value,
                &value.to_string(),
            )
        }
        (false, Some(status)) => zhipu_response(code, status),
        (false, None) => zhipu_stream(code),
    }
}

#[test]
fn every_table_code_has_nodes_reason_and_retryable_with_a_429() {
    let rows = rows();
    assert_eq!(rows.len(), 51, "42 zhipu codes and 9 plan codes");
    for row in rows {
        let code = row["code"].as_str().expect("code");
        let provider = provider_of(&verdict_for(code, Some(429)));
        assert_eq!(provider.code, code);
        assert_eq!(provider.status, Some(429), "{code}");
        assert_eq!(
            provider.reason,
            row["reason"].as_str().expect("reason"),
            "reason of {code} at 429"
        );
        assert_eq!(
            provider.retryable,
            row["retryable"].as_bool().expect("retryable"),
            "retryable of {code} at 429"
        );
    }
}

#[test]
fn every_table_code_has_nodes_reason_and_retryable_without_a_status() {
    for row in rows() {
        let code = row["code"].as_str().expect("code");
        let provider = provider_of(&verdict_for(code, None));
        assert_eq!(provider.status, None, "{code}");
        assert_eq!(
            provider.reason,
            row["reasonWithoutStatus"].as_str().expect("reason"),
            "reason of {code} without a status"
        );
        assert_eq!(
            provider.retryable,
            row["retryableWithoutStatus"].as_bool().expect("retryable"),
            "retryable of {code} without a status"
        );
    }
}
